create table if not exists public.sispro_institutions (id uuid primary key default gen_random_uuid(), name text not null unique check(length(name) between 1 and 200), active boolean not null default true, is_test boolean not null default false);
create table if not exists public.sispro_roles (id uuid primary key default gen_random_uuid(), institution_id uuid references public.sispro_institutions(id), name text not null check(length(name) between 1 and 120), active boolean not null default true, unique nulls not distinct(institution_id,name));
create table if not exists public.sispro_sectors (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.sispro_institutions(id), name text not null, active boolean not null default true, unique(institution_id,name), unique(institution_id,id));
create table if not exists public.sispro_cabinets (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.sispro_institutions(id), sector_id uuid, name text not null, active boolean not null default true, unique(institution_id,name), foreign key(institution_id,sector_id) references public.sispro_sectors(institution_id,id));
create table if not exists public.sispro_members (id uuid primary key default gen_random_uuid(), institution_id uuid references public.sispro_institutions(id), user_id uuid not null references auth.users(id), role_id uuid not null references public.sispro_roles(id), active boolean not null default true, unique nulls not distinct(institution_id,user_id));
create table if not exists public.sispro_mechanics (id text primary key, name text not null);
create table if not exists public.sispro_permissions (id uuid primary key default gen_random_uuid(), role_id uuid not null references public.sispro_roles(id), mechanic_id text not null references public.sispro_mechanics(id), access_level integer not null check(access_level between 0 and 3), unique(role_id,mechanic_id));
create table if not exists public.sispro_institution_mechanics (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.sispro_institutions(id), mechanic_id text not null references public.sispro_mechanics(id), enabled boolean not null default false, unique(institution_id,mechanic_id));
create or replace function sispro_private.is_ceo() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.sispro_profiles p where p.user_id=(select auth.uid()) and p.active and p.platform_role='ceo') and not coalesce((select auth.jwt()->>'is_anonymous')='true',false) $$;
revoke all on function sispro_private.is_ceo() from public,anon;
grant execute on function sispro_private.is_ceo() to authenticated;
do $$ declare t text; begin foreach t in array array['sispro_institutions','sispro_roles','sispro_sectors','sispro_cabinets','sispro_members','sispro_mechanics','sispro_permissions','sispro_institution_mechanics'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); execute format('grant select,insert,update on public.%I to authenticated',t); execute format('create policy ceo_admin on public.%I for all to authenticated using ((select sispro_private.is_ceo())) with check ((select sispro_private.is_ceo()))',t); end loop; end $$;
insert into public.sispro_institutions(name,is_test) values ('Procuradoria de Teste',true) on conflict(name) do nothing;
insert into public.sispro_roles(name) values ('Recursos Humanos'),('Moderador'),('Comercial') on conflict do nothing;
insert into public.sispro_roles(institution_id,name) select id,'Procurador' from public.sispro_institutions where is_test on conflict do nothing;
insert into public.sispro_mechanics(id,name) values ('processos','Processos'),('prazos','Prazos'),('agenda','Agenda'),('autos','Autos'),('jurisprudencia','Jurisprudência'),('usuarios','Usuários'),('gabinetes','Gabinetes'),('setores','Setores') on conflict do nothing;
create or replace function sispro_private.check_member_scope() returns trigger language plpgsql set search_path='' as $$ begin if not exists(select 1 from public.sispro_roles r where r.id=new.role_id and r.institution_id is not distinct from new.institution_id) then raise exception 'Cargo fora da instituição'; end if; return new; end $$;
create trigger sispro_member_scope before insert or update on public.sispro_members for each row execute function sispro_private.check_member_scope();
